begin
  if exists (select 1 from benchmark_workouts where slug in ('adrian', 'alec', 'alexander', 'andy', 'artie', 'barraza', 'bell', 'bowen', 'brehm', 'brenton', 'brian', 'bruck', 'bulger')) then raise exception 'slug exists'; end if;
  insert into benchmark_workouts (name, slug, category, subcategory, format, scheme, duration_estimate, difficulty, body_focus, equipment, scoring_type, description, movements, scoring_notes, tips, coaching_tips, scaling_notes, faqs, youtube_url) values
  ('Adrian',
   'adrian',
   'hero',
   null,
   'For Time',
   '7 Rounds For Time',
   '20–30 min',
   'advanced',
   'full-body',
   array['pullUpBar','box','bodyweight']::text[],
   'time',
   'Adrian honors U.S. Army Sgt. 1st Class Adrian Elizalde, 30, of North Bend, Oregon, of the 2nd Battalion, 1st Special Forces Group (Airborne). He died on Aug. 23, 2007, in Baghdad, Iraq, of wounds from an improvised explosive device.

You complete seven rounds of 3 forward rolls, 5 wall climbs, 7 toes-to-bar and 9 box jumps (30 in / 24 in). That adds up to 21 rolls, 35 wall climbs, 49 toes-to-bar and 63 box jumps. The reps are small, but the wall climbs and toes-to-bar both tax your shoulders and grip, and the tall box punishes tired legs. Moving smoothly from the floor to the wall to the bar is a big part of a good time.',
   '[{"name": "Forward Rolls", "reps": "3", "tip": "Tuck your chin, roll across your upper back and come up onto your feet in one motion."}, {"name": "Wall Walks", "reps": "5", "tip": "CrossFit calls these wall climbs. Walk your feet up the wall and your hands in until your chest touches the wall, then walk back down under control."}, {"name": "Toes-to-Bar", "reps": "7", "tip": "Kick through from a tight hollow position so both feet touch the bar together."}, {"name": "Box Jumps", "reps": "9", "tip": "Land with your whole foot on the box and open your hips fully at the top. Step down to save your legs.", "rx_men": "30 in", "rx_women": "24 in"}]'::jsonb,
   'Record your finish time.',
   '["Stand up from the rolls before you walk to the wall", "Small sets on the toes-to-bar save your grip", "Step down from the box on every rep"]'::jsonb,
   '["Take a breath after the forward rolls so you are not dizzy when you start the wall climbs.", "On each wall climb, keep your midline tight and walk your hands close enough to touch your chest to the wall.", "Plan to break the toes-to-bar into sets such as 4 and 3 once your grip starts to fade.", "Use a steady rhythm on the box jumps instead of rebounding, since the 30 in / 24 in box gets tall when you are tired.", "Set up the box, bar and wall close together so the transitions stay short."]'::jsonb,
   'Use a lower box, such as 24 in / 20 in, or step up instead of jumping. Replace wall climbs with a shorter walk up the wall, a plank hold with shoulder taps, or pike push-ups. Hanging knee raises can replace toes-to-bar, and a rocking roll on your back can replace the forward roll. Cut to five rounds if seven would take more than about 30 minutes.',
   '[{"question": "What is the Adrian workout?", "answer": "7 rounds for time of 3 forward rolls, 5 wall climbs, 7 toes-to-bar and 9 box jumps (30 in / 24 in)."}, {"question": "How many total reps are in Adrian?", "answer": "21 forward rolls, 35 wall climbs, 49 toes-to-bar and 63 box jumps."}, {"question": "What is a wall climb?", "answer": "Start face down with your feet against a wall, walk your feet up the wall and your hands toward it until your chest touches, then walk back down. It is the same movement as a wall walk."}, {"question": "Who was Adrian?", "answer": "U.S. Army Sgt. 1st Class Adrian Elizalde, 30, of the 2nd Battalion, 1st Special Forces Group (Airborne). He died on Aug. 23, 2007, in Baghdad, Iraq."}]'::jsonb,
   'https://www.youtube.com/watch?v=E1Q11m171mk'),
  ('Alec',
   'alec',
   'hero',
   null,
   'For Time',
   'For Time (3 Parts)',
   '35–50 min',
   'advanced',
   'full-body',
   array['running','sandbag','barbell','box','bodyweight']::text[],
   'time',
   'Alec honors Marine Lance Cpl. Alec E. Catherwood, 19, of Byron, Illinois, of the 3rd Battalion, 5th Marine Regiment, 1st Marine Division. He was killed by small-arms fire on Oct. 14, 2010, while deployed in Helmand Province, Afghanistan.

The workout has three parts done straight through. First, three rounds of 8 burpees, 28 air squats and 9 push-ups. Then a 1,000 m run, 25 over-the-shoulder sandbag cleans (100 lb / 75 lb) and another 1,000 m run. Last, five rounds of 10 deadlifts (225 lb / 155 lb), 14 box jumps (24 in / 20 in) and 10 burpees. That is 74 burpees, 2,000 m of running and a heavy bag in the middle. The final part comes when your legs and back are already tired.',
   '[{"name": "Burpees", "reps": "8", "tip": "Part 1: 3 rounds. Chest to the floor and a small jump at the top. Keep the pace easy, there is a long way to go."}, {"name": "Air Squats", "reps": "28", "tip": "Part 1: 3 rounds. Hips below the knees and stand all the way up."}, {"name": "Push-Ups", "reps": "9", "tip": "Part 1: 3 rounds. Straight body line and chest to the floor."}, {"name": "Run", "reps": "1,000 m", "tip": "Part 2. Settle into a pace you can hold, since the sandbag comes next."}, {"name": "Over-the-Shoulder Sandbag Cleans", "reps": "25", "tip": "Part 2. Lap the bag, stand tall and roll it over one shoulder. Let it drop behind you and turn to the next rep.", "rx_men": "100 lb", "rx_women": "75 lb"}, {"name": "Run", "reps": "1,000 m", "tip": "Part 2. Shake out your arms and breathe. Part 3 starts as soon as you get back."}, {"name": "Deadlifts", "reps": "10", "tip": "Part 3: 5 rounds. Brace before every pull and keep the bar close to your legs.", "rx_men": "225 lb", "rx_women": "155 lb"}, {"name": "Box Jumps", "reps": "14", "tip": "Part 3: 5 rounds. Step down on every rep to protect your legs.", "rx_men": "24 in", "rx_women": "20 in"}, {"name": "Burpees", "reps": "10", "tip": "Part 3: 5 rounds. Same steady rhythm as Part 1, just more tired."}]'::jsonb,
   'Record your finish time.',
   '["Treat Part 1 as a warm-up you are scored on", "Steady runs, not fast ones", "Break the deadlifts early, such as 5 and 5"]'::jsonb,
   '["Start the burpees, squats and push-ups at a pace you could hold for an hour, because the hardest part is at the end.", "On the sandbag cleans, keep the bag close, hinge at the hips and use your legs to drive it up onto your shoulder.", "Use the second 1,000 m run to bring your breathing down before the deadlifts.", "On the deadlifts, a set of 5 and 5 or quick singles is safer than grinding out ten reps with a rounded back.", "Step down from the box and move straight into the burpees so the rounds stay steady."]'::jsonb,
   'Lower the sandbag to 60–80 lb / 40–60 lb, or do the cleans with a lighter bag or a slam ball. Use 135 lb / 95 lb on the deadlifts and a 20 in / 16 in box, or step up. Cut each run to 600 m, or row 1,000 m instead. If the full workout would go past about an hour, do 3 rounds in Part 3.',
   '[{"question": "What is the Alec workout?", "answer": "For time: 3 rounds of 8 burpees, 28 air squats and 9 push-ups; then run 1,000 m, do 25 over-the-shoulder sandbag cleans and run 1,000 m; then 5 rounds of 10 deadlifts, 14 box jumps and 10 burpees."}, {"question": "What are the Rx weights for Alec?", "answer": "A 100 lb sandbag, 225 lb deadlift and 24 in box for men, and a 75 lb sandbag, 155 lb deadlift and 20 in box for women."}, {"question": "How many total reps are in Alec?", "answer": "74 burpees, 84 air squats, 27 push-ups, 25 sandbag cleans, 50 deadlifts and 70 box jumps, plus 2,000 m of running."}, {"question": "Who was Alec?", "answer": "Marine Lance Cpl. Alec E. Catherwood, 19, of the 3rd Battalion, 5th Marine Regiment, 1st Marine Division. He died on Oct. 14, 2010, in Helmand Province, Afghanistan."}]'::jsonb,
   null),
  ('Alexander',
